// Nó: Preparar Arquivo
// Converte o arquivo recebido para base64 e extrai metadados

const items = $input.all();
const results = [];

for (const item of items) {
  const body = item.json.body || item.json;
  const files = item.binary || {};

  let fileBase64 = null;
  let fileName = null;
  let fileType = null;
  let fileSize = null;

  // Verificar se veio arquivo binário
  if (Object.keys(files).length > 0) {
    const fileKey = Object.keys(files)[0];
    const file = files[fileKey];
    fileBase64 = file.data;
    fileName = file.fileName || 'comprovante';
    fileType = file.mimeType?.split('/')[1] || 'unknown';
    fileSize = file.fileSize || 0;
  } 
  // Ou se veio base64 no body
  else if (body.file_base64) {
    fileBase64 = body.file_base64;
    fileName = body.file_name || 'comprovante';
    fileType = body.file_type || 'unknown';
    fileSize = body.file_size || 0;
  }

  if (!fileBase64) {
    throw new Error('Nenhum arquivo encontrado na requisição');
  }

  // Determinar se precisa de OCR ou pode ir direto para IA com visão
  const needsOcr = fileType === 'pdf';
  const isImage = ['jpg', 'jpeg', 'png', 'webp'].includes(fileType);

  results.push({
    json: {
      file_base64: fileBase64,
      file_name: fileName,
      file_type: fileType,
      file_size: fileSize,
      needs_ocr: needsOcr,
      is_image: isImage,
      user_id: body.user_id || null,
      metadata: body.metadata || {}
    }
  });
}

return results;

// Nó: Preparar Texto OCR
// Extrai o texto do resultado do OCR e prepara para a IA

const items = $input.all();
const results = [];

for (const item of items) {
  const ocrResult = item.json;
  const prevData = $('Preparar Arquivo').first().json;

  let textoExtraido = '';

  if (ocrResult.ParsedResults && ocrResult.ParsedResults.length > 0) {
    textoExtraido = ocrResult.ParsedResults
      .map(r => r.ParsedText)
      .join('\n');
  }

  if (!textoExtraido || textoExtraido.trim() === '') {
    textoExtraido = 'Erro: Não foi possível extrair texto do documento.';
  }

  results.push({
    json: {
      texto_ocr: textoExtraido,
      file_base64: prevData.file_base64,
      file_name: prevData.file_name,
      file_type: prevData.file_type,
      file_size: prevData.file_size,
      user_id: prevData.user_id,
      metadata: prevData.metadata,
      ocr_success: textoExtraido.length > 50
    }
  });
}

return results;

// Nó: Validar e Normalizar Dados
// Valida os dados extraídos pela IA e normaliza os formatos

const items = $input.all();
const results = [];

for (const item of items) {
  // Pegar resposta da IA
  let iaResponse = item.json.message?.content || item.json.content || item.json;

  // Se for string, fazer parse do JSON
  if (typeof iaResponse === 'string') {
    try {
      iaResponse = JSON.parse(iaResponse);
    } catch (e) {
      // Tentar extrair JSON de dentro do texto
      const jsonMatch = iaResponse.match(/\{[\s\S]*\}/);
      if (jsonMatch) {
        iaResponse = JSON.parse(jsonMatch[0]);
      } else {
        throw new Error('Resposta da IA não é um JSON válido');
      }
    }
  }

  // Buscar dados do arquivo original
  const fileData = $('Preparar Arquivo').first().json;

  // Funções de validação
  const normalizeDate = (dateStr) => {
    if (!dateStr) return null;
    // Se já está no formato correto
    if (/^\d{4}-\d{2}-\d{2}$/.test(dateStr)) return dateStr;
    // Tentar converter DD/MM/YYYY
    const match = dateStr.match(/(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{2,4})/);
    if (match) {
      const day = match[1].padStart(2, '0');
      const month = match[2].padStart(2, '0');
      let year = match[3];
      if (year.length === 2) year = '20' + year;
      return `${year}-${month}-${day}`;
    }
    return null;
  };

  const normalizeValue = (value) => {
    if (value === null || value === undefined) return null;
    if (typeof value === 'number') return value;
    // Remover R$, espaços e converter vírgula para ponto
    const cleaned = String(value)
      .replace(/[R$\s]/g, '')
      .replace(/\./g, '')
      .replace(',', '.');
    const num = parseFloat(cleaned);
    return isNaN(num) ? null : num;
  };

  const normalizeDocument = (doc) => {
    if (!doc) return null;
    // Remover tudo que não for número
    return String(doc).replace(/\D/g, '') || null;
  };

  const normalizeFormaPagamento = (forma) => {
    if (!forma) return null;
    const formaUpper = String(forma).toUpperCase();
    const mapping = {
      'PIX': 'PIX',
      'TED': 'TED',
      'DOC': 'DOC',
      'BOLETO': 'Boleto',
      'CARTAO DE CREDITO': 'Cartão de Crédito',
      'CARTÃO DE CRÉDITO': 'Cartão de Crédito',
      'CARTAO DE DEBITO': 'Cartão de Débito',
      'CARTÃO DE DÉBITO': 'Cartão de Débito',
      'DEBITO AUTOMATICO': 'Débito Automático',
      'DÉBITO AUTOMÁTICO': 'Débito Automático',
      'TRANSFERENCIA': 'Transferência Interna',
      'TRANSFERÊNCIA': 'Transferência Interna'
    };
    return mapping[formaUpper] || forma;
  };

  const normalizeTipoChavePix = (tipo) => {
    if (!tipo) return null;
    const tipoUpper = String(tipo).toUpperCase();
    const mapping = {
      'CPF': 'CPF',
      'CNPJ': 'CNPJ',
      'EMAIL': 'Email',
      'E-MAIL': 'Email',
      'TELEFONE': 'Telefone',
      'CELULAR': 'Telefone',
      'ALEATORIA': 'Aleatoria',
      'ALEATÓRIO': 'Aleatoria',
      'EVP': 'Aleatoria'
    };
    return mapping[tipoUpper] || null;
  };

  // Construir objeto normalizado
  const normalized = {
    // Dados do pagamento
    data_pagamento: normalizeDate(iaResponse.data_pagamento),
    valor: normalizeValue(iaResponse.valor),
    descricao: iaResponse.descricao || null,
    referencia: iaResponse.referencia || null,

    // Partes
    pagador: iaResponse.pagador || null,
    documento_pagador: normalizeDocument(iaResponse.documento_pagador),
    favorecido: iaResponse.favorecido || null,
    documento_favorecido: normalizeDocument(iaResponse.documento_favorecido),

    // Transação
    forma_pagamento: normalizeFormaPagamento(iaResponse.forma_pagamento),
    identificador_transacao: iaResponse.identificador_transacao || null,
    codigo_autenticacao: iaResponse.codigo_autenticacao || null,

    // Bancos
    banco_origem: iaResponse.banco_origem || null,
    agencia_origem: normalizeDocument(iaResponse.agencia_origem),
    conta_origem: normalizeDocument(iaResponse.conta_origem),
    banco_destino: iaResponse.banco_destino || null,
    agencia_destino: normalizeDocument(iaResponse.agencia_destino),
    conta_destino: normalizeDocument(iaResponse.conta_destino),

    // PIX
    chave_pix: iaResponse.chave_pix || null,
    tipo_chave_pix: normalizeTipoChavePix(iaResponse.tipo_chave_pix),

    // Arquivo
    arquivo_original_nome: fileData.file_name,
    arquivo_tipo: fileData.file_type,
    arquivo_tamanho: fileData.file_size,

    // Metadados IA
    confianca_extracao: iaResponse.confianca || 80,
    texto_ocr: $('Preparar Texto OCR').first()?.json?.texto_ocr || null,
    dados_brutos_ia: iaResponse,
    observacoes_ia: iaResponse.observacoes || null,

    // Rastreabilidade
    status: 'processado',
    user_id: fileData.user_id,
    origem: 'n8n',
    workflow_execution_id: $execution.id
  };

  // Verificar se há campos críticos ausentes
  const warnings = [];
  if (!normalized.data_pagamento) warnings.push('Data de pagamento não identificada');
  if (!normalized.valor) warnings.push('Valor não identificado');
  if (!normalized.forma_pagamento) warnings.push('Forma de pagamento não identificada');

  if (warnings.length > 0) {
    normalized.observacoes_ia = [normalized.observacoes_ia, ...warnings].filter(Boolean).join('; ');
    normalized.status = warnings.length >= 2 ? 'revisao_manual' : 'processado';
    normalized.confianca_extracao = Math.max(0, normalized.confianca_extracao - (warnings.length * 15));
  }

  results.push({ json: normalized });
}

return results;

// Nó: Tratar Erro
// Prepara resposta de erro para o webhook

const item = $input.first();
const errorMessage = item.json.message || item.json.error || 'Erro desconhecido ao processar comprovante';

return [{
  json: {
    success: false,
    error: errorMessage,
    execution_id: $execution.id,
    timestamp: new Date().toISOString()
  }
}];
